from datetime import datetime, timedelta

import pytest
from isoduration import add_duration


class TestBasicComponents:
    """Test single components: years, months, weeks, days, hours, minutes, seconds."""

    def test_years_single(self):
        assert add_duration(datetime(2020, 1, 15), "P1Y") == datetime(2021, 1, 15)

    def test_years_multiple(self):
        assert add_duration(datetime(2020, 1, 15), "P5Y") == datetime(2025, 1, 15)

    def test_months_single(self):
        assert add_duration(datetime(2020, 1, 15), "P1M") == datetime(2020, 2, 15)

    def test_months_multiple(self):
        assert add_duration(datetime(2020, 1, 15), "P10M") == datetime(2020, 11, 15)

    def test_weeks_single(self):
        assert add_duration(datetime(2020, 1, 1), "P1W") == datetime(2020, 1, 8)

    def test_weeks_multiple(self):
        assert add_duration(datetime(2020, 1, 1), "P2W") == datetime(2020, 1, 15)

    def test_days_single(self):
        assert add_duration(datetime(2020, 1, 15), "P1D") == datetime(2020, 1, 16)

    def test_days_multiple(self):
        assert add_duration(datetime(2020, 1, 15), "P10D") == datetime(2020, 1, 25)

    def test_hours_single(self):
        assert add_duration(datetime(2020, 1, 15, 10, 0), "PT1H") == datetime(2020, 1, 15, 11, 0)

    def test_hours_multiple(self):
        assert add_duration(datetime(2020, 1, 15, 10, 0), "PT5H") == datetime(2020, 1, 15, 15, 0)

    def test_minutes_single(self):
        assert add_duration(datetime(2020, 1, 15, 10, 0), "PT1M") == datetime(2020, 1, 15, 10, 1)

    def test_minutes_multiple(self):
        assert add_duration(datetime(2020, 1, 15, 10, 0), "PT30M") == datetime(2020, 1, 15, 10, 30)

    def test_seconds_single(self):
        assert add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT1S") == datetime(2020, 1, 15, 10, 0, 1)

    def test_seconds_multiple(self):
        assert add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT45S") == datetime(2020, 1, 15, 10, 0, 45)


class TestMultipleComponents:
    """Test combinations of multiple components."""

    def test_years_and_months(self):
        assert add_duration(datetime(2020, 1, 15), "P1Y2M") == datetime(2021, 3, 15)

    def test_years_months_days(self):
        assert add_duration(datetime(2020, 1, 15), "P1Y2M3D") == datetime(2021, 3, 18)

    def test_days_and_time(self):
        assert add_duration(datetime(2020, 1, 15, 10, 0, 0), "P1DT2H30M") == datetime(2020, 1, 16, 12, 30, 0)

    def test_years_months_days_time(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "P1Y2M3DT4H5M6S")
        assert result == datetime(2021, 3, 18, 14, 5, 6)

    def test_all_components(self):
        # P1Y2M10DT2H30M5S from README
        result = add_duration(datetime(2024, 1, 15, 10, 0, 0), "P1Y2M10DT2H30M5S")
        assert result == datetime(2025, 3, 25, 12, 30, 5)


class TestMonthEndHandling:
    """Test day-of-month adjustment when target month has fewer days."""

    def test_jan31_plus_one_month_to_feb(self):
        # Jan 31 + 1 month = Feb 29 (leap year)
        assert add_duration(datetime(2024, 1, 31), "P1M") == datetime(2024, 2, 29)

    def test_jan31_plus_one_month_to_feb_non_leap(self):
        # Jan 31 + 1 month = Feb 28 (non-leap year)
        assert add_duration(datetime(2023, 1, 31), "P1M") == datetime(2023, 2, 28)

    def test_jan31_plus_13_months(self):
        # Jan 31 + 13 months (1Y1M) = Feb 29 (leap year, 2024)
        assert add_duration(datetime(2024, 1, 31), "P1Y1M") == datetime(2025, 2, 28)

    def test_march31_minus_one_month(self):
        # Mar 31 - 1 month = Feb 29 (leap year)
        assert add_duration(datetime(2024, 3, 31), "-P1M") == datetime(2024, 2, 29)

    def test_feb29_plus_one_year_non_leap(self):
        # Feb 29, 2024 + 1 year = Feb 28, 2025 (non-leap)
        assert add_duration(datetime(2024, 2, 29), "P1Y") == datetime(2025, 2, 28)

    def test_march31_plus_11_months(self):
        # Mar 31 + 11 months = Feb 28/29 (wraps to next year)
        result = add_duration(datetime(2024, 3, 31), "P11M")
        assert result == datetime(2025, 2, 28)

    def test_may31_plus_6_months(self):
        # May 31 + 6 months = Nov 30
        assert add_duration(datetime(2024, 5, 31), "P6M") == datetime(2024, 11, 30)

    def test_hours_minutes_seconds_preserved_during_month_adjustment(self):
        # Verify time is preserved during month end adjustment
        assert add_duration(datetime(2024, 1, 31, 15, 30, 45), "P1M") == datetime(2024, 2, 29, 15, 30, 45)


class TestNegativeDurations:
    """Test durations with negative sign."""

    def test_negative_days(self):
        assert add_duration(datetime(2020, 1, 15), "-P1D") == datetime(2020, 1, 14)

    def test_negative_months(self):
        assert add_duration(datetime(2020, 3, 15), "-P1M") == datetime(2020, 2, 15)

    def test_negative_years(self):
        assert add_duration(datetime(2020, 1, 15), "-P1Y") == datetime(2019, 1, 15)

    def test_negative_months_then_days(self):
        # Mar 31 - P1M1D: first back one month to Feb 29, then back one day
        assert add_duration(datetime(2024, 3, 31), "-P1M1D") == datetime(2024, 1, 31)

    def test_negative_time(self):
        assert add_duration(datetime(2020, 1, 15, 15, 30), "-PT2H") == datetime(2020, 1, 15, 13, 30)

    def test_positive_sign_explicit(self):
        # Explicit positive sign should work
        assert add_duration(datetime(2020, 1, 15), "+P1D") == datetime(2020, 1, 16)


class TestFractionalComponents:
    """Test fractional parts in duration components."""

    def test_fractional_seconds(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT1.5S")
        assert result == datetime(2020, 1, 15, 10, 0, 1, 500000)

    def test_fractional_seconds_comma_separator(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT1,5S")
        assert result == datetime(2020, 1, 15, 10, 0, 1, 500000)

    def test_fractional_minutes(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT1.5M")
        assert result == datetime(2020, 1, 15, 10, 1, 30)

    def test_fractional_hours(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT1.5H")
        assert result == datetime(2020, 1, 15, 11, 30, 0)

    def test_fractional_days(self):
        # 0.5D = 12 hours
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "P0.5D")
        assert result == datetime(2020, 1, 15, 22, 0, 0)

    def test_fractional_weeks(self):
        # 1.5W = 10.5 days
        result = add_duration(datetime(2020, 1, 1, 0, 0, 0), "P1.5W")
        assert result == datetime(2020, 1, 11, 12, 0, 0)

    def test_fractional_seconds_many_decimals(self):
        # Microsecond precision, should round to nearest microsecond
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT1.123456S")
        assert result.microsecond == 123456

    def test_fractional_seconds_rounding(self):
        # Test rounding to nearest microsecond
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT0.0000001S")
        # Should round to 0 microseconds or handle appropriately
        assert isinstance(result, datetime)


class TestSyntaxValidation:
    """Test syntax validation and error handling."""

    def test_missing_p_designator(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "1Y")

    def test_only_p_designator(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P")

    def test_p_with_only_t(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "PT")

    def test_p_with_days_but_no_time_after_t(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1DT")

    def test_whitespace_in_duration(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P 1D")

    def test_sign_on_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P-1D")

    def test_lowercase_designators(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "p1d")

    def test_mixed_case_designators(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1d")

    def test_weeks_with_days(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 1), "P2W3D")

    def test_weeks_with_hours(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 1), "P2WT1H")

    def test_component_out_of_order(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1D1Y")

    def test_duplicate_months_before_t(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1M2M")

    def test_duplicate_days(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1D2D")

    def test_duplicate_hours(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "PT1H2H")

    def test_minute_before_t_invalid(self):
        # M before T means months, not minutes - should be in time section
        result = add_duration(datetime(2020, 1, 15), "P1M")
        assert result == datetime(2020, 2, 15)

    def test_no_digits_after_designator(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "PY")

    def test_fraction_on_years(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1.5Y")

    def test_fraction_on_months(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1.5M")

    def test_fraction_not_on_last_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1.5DT1H")

    def test_fraction_missing_integer_part(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15, 10, 0), "PT.5S")

    def test_fraction_missing_decimal_part(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15, 10, 0), "PT1.S")

    def test_multiple_decimal_separators(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15, 10, 0), "PT1.5.5S")

    def test_invalid_decimal_separator(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15, 10, 0), "PT1-5S")

    def test_empty_string(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "")

    def test_t_without_time_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1DT")

    def test_multiple_t_designators(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1DT1HT2M")


class TestComplexScenarios:
    """Test complex real-world scenarios."""

    def test_leap_year_february_plus_months(self):
        # Feb 29, 2024 + 12 months = Feb 28, 2025 (non-leap)
        assert add_duration(datetime(2024, 2, 29), "P12M") == datetime(2025, 2, 28)

    def test_crossing_year_boundary(self):
        result = add_duration(datetime(2024, 12, 15), "P2M")
        assert result == datetime(2025, 2, 15)

    def test_crossing_year_boundary_negative(self):
        result = add_duration(datetime(2025, 1, 15), "-P2M")
        assert result == datetime(2024, 11, 15)

    def test_crossing_multiple_year_boundaries(self):
        result = add_duration(datetime(2024, 11, 15), "P10Y")
        assert result == datetime(2034, 11, 15)

    def test_mixed_positive_and_fractional(self):
        # 1 day and 12 hours = 36 hours total
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "P1DT12H")
        assert result == datetime(2020, 1, 16, 22, 0, 0)

    def test_zero_months_wrapping(self):
        # Test that going back multiple months wraps correctly
        result = add_duration(datetime(2024, 1, 31), "-P13M")
        assert result == datetime(2022, 12, 31)

    def test_time_with_microseconds_preserved(self):
        dt = datetime(2020, 1, 15, 10, 30, 45, 123456)
        result = add_duration(dt, "P1D")
        assert result.microsecond == 123456

    def test_large_duration(self):
        result = add_duration(datetime(2000, 1, 1), "P100Y")
        assert result == datetime(2100, 1, 1)


class TestBoundaryConditions:
    """Test boundary conditions and edge cases."""

    def test_zero_days(self):
        dt = datetime(2020, 1, 15)
        result = add_duration(dt, "P0D")
        assert result == dt

    def test_zero_months(self):
        dt = datetime(2020, 1, 15)
        result = add_duration(dt, "P0M")
        assert result == dt

    def test_zero_time(self):
        dt = datetime(2020, 1, 15, 10, 0, 0)
        result = add_duration(dt, "PT0S")
        assert result == dt

    def test_very_small_fractional_seconds(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT0.000001S")
        assert result.microsecond == 1

    def test_max_days_in_month_handling(self):
        # Test all month-end scenarios
        may31 = datetime(2024, 5, 31)
        assert add_duration(may31, "P6M") == datetime(2024, 11, 30)
        assert add_duration(may31, "-P5M") == datetime(2023, 12, 31)

    def test_leading_zeros_in_components(self):
        result = add_duration(datetime(2020, 1, 15), "P001Y002M003D")
        assert result == datetime(2021, 3, 18)

    def test_large_hours_component(self):
        result = add_duration(datetime(2020, 1, 15), "PT100H")
        assert result == datetime(2020, 1, 19, 4, 0, 0)

    def test_large_minutes_component(self):
        result = add_duration(datetime(2020, 1, 15), "PT1000M")
        assert result == datetime(2020, 1, 15, 16, 40, 0)

    def test_large_seconds_component(self):
        result = add_duration(datetime(2020, 1, 15), "PT10000S")
        assert result == datetime(2020, 1, 15, 2, 46, 40)

    def test_datetime_min_boundary(self):
        # Test that we can handle dates close to datetime.min
        dt = datetime(1, 1, 1)
        result = add_duration(dt, "P100Y")
        assert result.year == 101

    def test_datetime_max_boundary(self):
        # Test that we can handle dates close to datetime.max
        dt = datetime(9999, 12, 31)
        result = add_duration(dt, "-P100Y")
        assert result.year == 9899

    def test_overflow_raises_error(self):
        # datetime.max is year 9999, adding more years should raise ValueError
        dt = datetime(9999, 1, 1)
        with pytest.raises(ValueError):
            add_duration(dt, "P1Y")

    def test_underflow_raises_error(self):
        # datetime.min is year 1, subtracting should raise ValueError
        dt = datetime(1, 1, 1)
        with pytest.raises(ValueError):
            add_duration(dt, "-P1Y")


class TestTimezoneNaive:
    """Test that all datetimes are treated as naive (no timezone handling)."""

    def test_naive_datetime_in(self):
        # Input should be naive
        dt = datetime(2020, 1, 15, 10, 30)
        assert dt.tzinfo is None
        result = add_duration(dt, "P1D")
        assert result.tzinfo is None

    def test_naive_datetime_out(self):
        # Output should be naive
        result = add_duration(datetime(2020, 1, 15, 10, 30), "P1D")
        assert result.tzinfo is None


class TestLeadingZeros:
    """Test parsing of leading zeros in numeric components."""

    def test_leading_zero_years(self):
        result = add_duration(datetime(2020, 1, 15), "P02Y")
        assert result == datetime(2022, 1, 15)

    def test_leading_zero_months(self):
        result = add_duration(datetime(2020, 1, 15), "P03M")
        assert result == datetime(2020, 4, 15)

    def test_leading_zero_days(self):
        result = add_duration(datetime(2020, 1, 15), "P05D")
        assert result == datetime(2020, 1, 20)

    def test_leading_zero_hours(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0), "PT02H")
        assert result == datetime(2020, 1, 15, 12, 0)

    def test_leading_zero_minutes(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0), "PT05M")
        assert result == datetime(2020, 1, 15, 10, 5)

    def test_leading_zero_seconds(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0), "PT03S")
        assert result == datetime(2020, 1, 15, 10, 0, 3)

    def test_leading_zero_fractional(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0), "PT0.5S")
        assert result == datetime(2020, 1, 15, 10, 0, 0, 500000)
